package acme.ledger.application.write;
public final class WriteUseCase implements WriteInputPort {private final EntryRepository entries;private final dev.domaincentric.dca.buildingblocks.hexagonal.port.out.DomainEventPublisher events;private final dev.domaincentric.dca.buildingblocks.application.TransactionBoundary boundary;public WriteUseCase(EntryRepository entries,dev.domaincentric.dca.buildingblocks.hexagonal.port.out.DomainEventPublisher events,dev.domaincentric.dca.buildingblocks.application.TransactionBoundary boundary){this.entries=entries;this.events=events;this.boundary=boundary;}public WriteResult execute(WriteCommand command){return boundary.inTransaction(()->{var entry=new acme.ledger.domain.model.Entry(new acme.ledger.domain.model.EntryId(command.id()));entry.change();entries.save(entry);events.publishAndClearEvents(entry);return new WriteResult(command.id());});}}
